    @Test void aliasedNativeImagesAndDirectoryDuplicatesKeepContextAndLifetimeChecks() throws Exception {
        int imageSize=size(); for(var backend:List.of("ast","bytecode")) try(var first=context()) { first.initialize("thc"); first.enter(); try { var language=TruffleLanguage.LanguageReference.create(Language.class).get(null); var scratch=setup(); var state=Language.currentState(); long fd=open(scratch); long duplicate=state.getStdio().duplicate(fd); assertTrue(duplicate>=3); assertNotEquals(fd,duplicate); assertEquals(0L,state.getStdio().close(fd)); var entry=program(language,backend,raw()).entryTarget("entry"); var base=state.getNativeAllocations().malloc(imageSize+16L); var alias=base.plus(8); try { base.fill(imageSize+16L,90);
            // Path bytes and the output share an allocation. The input snapshot
            // must finish before successful stat publication overwrites it.
            ManagedAddress.fromByteArray(new byte[]{116,97,114,103,101,116,0}).copyNonOverlappingTo(alias,7); try(var second=context()) { second.initialize("thc"); second.enter(); try { var other=TruffleLanguage.LanguageReference.create(Language.class).get(null); var foreign=program(other,backend,raw()).entryTarget("entry"); assertThrows(RuntimeFault.class,()->callScalarTestTarget(foreign,new Object[]{0L,(int)duplicate,cstring("target"),alias,0,thc.runtime.Unit.INSTANCE})); byte[] untouched=new byte[imageSize]; Arrays.fill(untouched,(byte)90); assertEquals(-1,callScalarTestTarget(foreign,new Object[]{0L,(int)duplicate,cstring("target"),ManagedAddress.fromByteArray(untouched),0,thc.runtime.Unit.INSTANCE})); assertEquals(StdioHostAbi.load().error(4),Language.currentState().getStdio().errno()); for(byte value:untouched) assertEquals((byte)90,value); released(other); } finally { second.leave(); } } assertEquals(0,callScalarTestTarget(entry,new Object[]{0L,(int)duplicate,alias,alias,0,thc.runtime.Unit.INSTANCE})); assertEquals(32L,field(alias,OriginalStdioOp.ST_SIZE)); for(long i=0;i<=7;i++) { assertEquals(90L,base.readWord8(i)); assertEquals(90L,base.readWord8(imageSize+8L+i)); } assertEquals(0L,state.getStdio().close(duplicate)); base.fill(imageSize+16L,90); assertEquals(-1,callScalarTestTarget(entry,new Object[]{0L,(int)duplicate,cstring("target"),alias,0,thc.runtime.Unit.INSTANCE})); for(long i=0;i<imageSize+16L;i++) assertEquals(90L,base.readWord8(i)); } finally { state.getNativeAllocations().free(base); } assertThrows(RuntimeFault.class,()->callScalarTestTarget(entry,new Object[]{0L,(int)StdioHostAbi.load().getAtFdcwd(),cstring(scratch.resolve("target").toString()),alias,0,thc.runtime.Unit.INSTANCE})); released(language); } finally { first.leave(); } }
    }
